function gml_Script_s_do_postmatch_dilemma(e, _) {
    {
        var t = GetWithArray(YYASSET_REF(98));
        for (var r in t)
            if (t.hasOwnProperty(r)) {
                var l = t[r];
                {
                    if (yyGetBool(l.gmlqb_mode) && yyGetBool(gml_Script_s_qb_mode_benched_status(l, e))) {
                        gml_Script_s_play(l, e, 1);
                        return;
                    }
                    var a = gml_Script_s_get_random_player(l, e, !1)
                      , s = ""
                      , o = gml_Script_s_get_human_fixture_by_week(l, e, l.gmlweek);
                    yyGetBool(yyfgreater(l.gmlweek, 4)) && yyGetBool(yyfless(l.gmlweek, gml_Script_s_get_week_superbowl(l, e))) && yyGetBool(a) && yyGetBool(yyflessequal(ds_map_find_value(a, "attitude"), 15)) ? (s = gml_Script_s_choose_dilemma(l, e, "postmatch_toxic")) : yyGetBool(a) && yyGetBool(yyfgreater(gml_Script_s_get_match_rating(l, e, a), 7)) ? (s = gml_Script_s_choose_dilemma(l, e, "postmatch_performance_good")) : yyGetBool(yyfless(l.gmlweek, gml_Script_s_get_week_superbowl(l, e))) && yyGetBool(a) && yyGetBool(yyfless(gml_Script_s_get_match_rating(l, e, a), 4)) ? (s = gml_Script_s_choose_dilemma(l, e, "postmatch_performance_bad")) : yyGetBool(a) && yyGetBool(!yyGetBool(irandom(4))) ? yyGetBool(irandom(4)) ? (s = gml_Script_s_choose_dilemma(l, e, "postmatch_question_player")) : ((a = gml_Script_s_get_random_coach(l, e)),
                    (s = gml_Script_s_choose_dilemma(l, e, "postmatch_question_staff"))) : yyfequal(ds_map_find_value(o, "human_win"), "loss") ? (s = gml_Script_s_choose_dilemma(l, e, "postmatch_loss")) : yyfequal(ds_map_find_value(o, "human_win"), "win") ? (s = gml_Script_s_choose_dilemma(l, e, "postmatch_win")) : yyGetBool(a) && (s = gml_Script_s_choose_dilemma(l, e, "postmatch_question_player")),
                    yyfnotequal(s, "") ? (ds_map_clear(l.gmlmap_dilemma),
                    (l.gmlmap_dilemma = gml_Script_s_parse_dilemma(l, e, s, a, "ui_PressInterview")),
                    (yyInst(e, _, YYASSET_REF(98)).gmlplayer_profile = a),
                    gml_Script_s_create_dilemma(l, e, l.gmlmap_dilemma)) : gml_Script_s_play(l, e, 1);
                }
            }
    }
}
