function gml_RoomCC_rm_stats_player_22_Create(e, _) {
    var t = ds_map_find_value(yyInst(e, _, YYASSET_REF(98)).gmlplayer_profile, "position")
      , r = -1;
    switch (((yyCompareVal(t, 1, g_GMLMathEpsilon, !1) == 0 || yyCompareVal(t, 2, g_GMLMathEpsilon, !1) == 0) && (r = 0),
    r)) {
    case 0:
        break;
    default:
        e.visible = !1;
    }
    yyfequal(yyInst(e, _, YYASSET_REF(98)).gmlstat_view, 2) && (e.gmlcolour = global.gmlc_primary),
    yyGetBool(gml_Script_s_is_co_mode(e, e)) && (e.visible = !1);
}
